const now = new Date(msg.payload);
msg.payload = {
    datetime: {
        year: now.getFullYear(),
        month: now.getMonth() + 1,
        day: now.getDate(),
        weekday: now.getDay(), // JS and PCF8523 both use Sunday=0
        hour: now.getHours(),
        minute: now.getMinutes(),
        second: now.getSeconds()
    }
};
return msg;

const p = msg.payload;
if (p && p.source === 'timer_b') {
    msg.payload = 'still alive (Timer B heartbeat)';
} else if (p && p.source) {
    msg.payload = `interrupt: ${p.source}`;
} else if (p && p.year !== undefined) {
    const pad = (n) => String(n).padStart(2, '0');
    msg.payload = `${p.year}-${pad(p.month)}-${pad(p.day)} ${pad(p.hour)}:${pad(p.minute)}:${pad(p.second)}` +
        `  battery_low=${p.battery_low} switched_over=${p.battery_switched_over}`;
}
return msg;
